const source = $('Execute Workflow Trigger').item.json || {};
const args = source.args || source.payload?.args || {};
const payload = source.payload || {};
const message = source.message || payload.message || {};
const chatId = source.chatId || message.chat?.id || '';
const raw = String(source.rawText || source.text || message.text || '').trim();

let cleaned = raw.replace(/^(tra loi mail|trả lời mail|tra loi email|trả lời email|reply mail|reply email)\s*/i, '').trim();
const explicitSearchQuery = String(source.searchQuery || args.searchQuery || '').trim();
const directMessageId = String(source.messageId || args.messageId || '').trim();
const directReplyBody = String(source.body || args.body || '').trim();

const parts = cleaned.split('\n').map((line) => line.trim()).filter(Boolean);
let searchQuery = explicitSearchQuery;
let replyBody = directReplyBody;

if (!replyBody && parts.length >= 2) {
  searchQuery = searchQuery || parts[0];
  replyBody = parts.slice(1).join('\n');
} else if (!replyBody && parts.length === 1) {
  const spaceParts = parts[0].split(/\s{2,}|\t/);
  if (spaceParts.length >= 2) {
    searchQuery = searchQuery || spaceParts[0];
    replyBody = spaceParts.slice(1).join(' ');
  }
}

const hasBody = Boolean(replyBody);
const hasExactTarget = Boolean(directMessageId);
const isReady = hasExactTarget && hasBody;

let response = '';
if (!hasBody) {
  response = [
    'Mia cần nội dung trả lời trước khi gửi email.',
    '',
    'Cách an toàn:',
    '- đọc email cần trả lời trước',
    '- sau đó reply bằng messageId cụ thể'
  ].join('\n');
} else if (!hasExactTarget) {
  response = [
    'Mia chưa gửi reply vì chưa có messageId cụ thể.',
    '',
    searchQuery ? `Từ khóa bạn đưa: ${searchQuery}` : '',
    'Để tránh trả lời nhầm email, hãy tìm/đọc email trước rồi reply đúng messageId.'
  ].filter(Boolean).join('\n');
}

return [{
  json: {
    ...source,
    chatId,
    messageId: directMessageId,
    searchQuery,
    replyBody,
    isReady,
    response
  }
}];

const source = $('Parse Tra Loi Email').item.json;

const pickFirst = (...values) => {
  for (const value of values) {
    if (value === undefined || value === null) continue;
    if (typeof value === 'string' && value.trim()) return value.trim();
  }
  return '';
};

const rows = $input.all().map((i) => i.json || {}).filter((e) => e.id);
if (!rows.length) {
  return [{ json: { ...source, canReply: false, response: '⚠️ Không tìm thấy email để trả lời.' } }];
}
const email = rows[0];
const subject = pickFirst(email.subject, email.Subject, email.payload?.headers?.find((h) => h.name === 'Subject')?.value);
const threadId = email.threadId || email.id || '';
return [{ json: { ...source, canReply: true, messageId: email.id, threadId, subject } }];

const source = $('Parse Tra Loi Email').item.json;
const reply = $('Chon Email Reply').item.json;
const escapeHtml = (value = '') => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/\"/g, '&quot;');

const threadId = reply.threadId || '';
const link = threadId ? `https://mail.google.com/mail/u/0/#inbox/${threadId}` : '';

let text = '✅ <b>Đã trả lời email</b>\n\n';
if (reply.subject) text += `📝 Re: ${escapeHtml(reply.subject)}\n`;
text += `📄 ${escapeHtml(source.replyBody.substring(0, 200))}`;
if (source.replyBody.length > 200) text += '...';
if (link) text += `\n🔗 <a href="${escapeHtml(link)}">Xem cuộc trò chuyện</a>`;
return [{ json: { chatId: source.chatId, text } }];

const source = $json || {};

function decodeEntities(value = '') {
  return String(value)
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'");
}

function htmlToPlainText(value = '') {
  return decodeEntities(String(value || ''))
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<li>/gi, '- ')
    .replace(/<\/h\d>/gi, '\n')
    .replace(/<a[^>]*href="([^"]+)"[^>]*>(.*?)<\/a>/gi, '$2: $1')
    .replace(/<[^>]+>/g, ' ')
    .replace(/[ \t]+/g, ' ')
    .replace(/\s+([,.;:!?])/g, '$1')
    .replace(/\n\s+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const target =
  source.query ||
  source.docName ||
  source.sheetName ||
  source.fileName ||
  source.folderName ||
  source.targetName ||
  source.title ||
  source.summary ||
  source.rawText ||
  source.text ||
  '';

let text = htmlToPlainText(source.response || source.text || source.error || '');
if (!text) {
  text = target
    ? `Mia chưa xử lý được yêu cầu với "${target}". Bạn kiểm tra lại thông tin đầu vào giúp Mia nhé.`
    : 'Mia chưa đủ thông tin để xử lý yêu cầu này.';
}

return [{
  json: {
    ok: false,
    tool: source.tool || source.workflowKey || '',
    chatId: source.chatId || '',
    text,
    links: [],
    result: {},
    meta: {
      target: String(target || '').trim(),
      reason: source.hasTarget === false || source.isReady === false ? 'missing_required_input' : 'not_found_or_not_applicable'
    }
  }
}];
